package at.andrew.squashtap;

import android.app.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowDialog;
import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(sdk=34,application=Application.class,qualifiers="w233dp-h233dp-round") @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.LEGACY)
public class ManualScoreEntryUiTest {
    private ActivityController<MainActivity> controller;private MainActivity activity;private SharedPreferences preferences;private String martin,alice;
    @Before public void prepare(){preferences=RuntimeEnvironment.getApplication().getSharedPreferences("squash",0);MatchBook b=new MatchBook(new MatchState("current",3));b.add(0);b.add(1);b.add(0);OpponentDirectory d=new OpponentDirectory();martin=d.add("Martin");alice=d.add("Alice");d.assign("current",martin);preferences.edit().clear().putString("match_book",b.encode()).putString("opponent_book",d.encode()).putString(MatchDisplayPolicy.ACTIVE_MATCH,"current").putBoolean("asked_match_notification",true).commit();launch();}
    private void launch(){controller=Robolectric.buildActivity(MainActivity.class).setup();activity=controller.get();}
    private void close(){Dialog d=ShadowDialog.getLatestDialog();if(d!=null)d.dismiss();if(controller!=null){controller.pause().stop().destroy();controller=null;}}
    @After public void finish(){close();}
    private List<View> all(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(all(((ViewGroup)v).getChildAt(i)));return out;}
    private List<View> all(){return all(ShadowDialog.getLatestDialog().getWindow().getDecorView());}
    private Button button(String text){for(View v:all())if(v instanceof Button&&((Button)v).getText().toString().split("\n",2)[0].equals(text))return (Button)v;throw new AssertionError("Missing button: "+text);}
    private boolean has(String text){for(View v:all())if(v instanceof TextView&&((TextView)v).getText().toString().contains(text))return true;return false;}
    private void click(String text){button(text).performClick();}
    private MatchBook book(){return MatchBook.decode(preferences.getString("match_book",""));}
    private OpponentDirectory names(){return OpponentDirectory.decode(preferences.getString("opponent_book",""));}
    private NumberPicker wheel(){for(View v:all())if(v instanceof NumberPicker)return (NumberPicker)v;throw new AssertionError("Missing number wheel");}
    private void noKeyboard(){NumberPicker p=wheel();assertEquals(ViewGroup.FOCUS_BLOCK_DESCENDANTS,p.getDescendantFocusability());assertEquals(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN,ShadowDialog.getLatestDialog().getWindow().getAttributes().softInputMode&WindowManager.LayoutParams.SOFT_INPUT_MASK_STATE);}
    private void menu(){activity.action(TouchTargets.MENU);click("Current match");}
    private void currentSet(String winner,int loser){click("Enter set score");click(winner);wheel().setValue(loser);click("Review set score");click("Save set score");}
    private void history(){activity.action(TouchTargets.MENU);click("Results ("+book().count()+")");click("Add past match");}
    private void draftSet(int index,String winner,int loser){click("Add set "+index);click(winner);wheel().setValue(loser);click("Use set score");}
    @Test public void manualEntryLivesInMatchWithoutChangingTheMainControls(){activity.action(TouchTargets.MENU);assertFalse(has("Enter set score"));click("Current match");assertNotNull(button("Enter set score"));assertFalse(has("Add past match"));assertNull(button("Back to Menu").getBackgroundTintList());}
    @Test public void setEntryUsesTouchPresetsSteppersAndAKeyboardBlockedWheel(){menu();click("Enter set score");Button me=button("Me won"),op=button("Opponent won");assertTrue(Color.blue(me.getBackgroundTintList().getDefaultColor())>Color.red(me.getBackgroundTintList().getDefaultColor()));assertTrue(Color.red(op.getBackgroundTintList().getDefaultColor())>Color.blue(op.getBackgroundTintList().getDefaultColor()));click("Me won");noKeyboard();click("11–9");assertEquals(9,wheel().getValue());click("+");assertEquals(10,wheel().getValue());assertTrue(all().stream().anyMatch(v->v.getContentDescription()!=null&&v.getContentDescription().toString().contains("Me 12, Martin 10")));click("−");assertEquals(9,wheel().getValue());click("+");click("Review set score");click("Save set score");assertEquals(12,book().current().game().blue());assertEquals(10,book().current().game().red());}
    @Test public void opponentWinnerPresetsKeepMeFirstInTheEnteredScore(){menu();click("Enter set score");click("Opponent won");noKeyboard();click("9–11");click("Review set score");click("Save set score");assertEquals(9,book().current().game().blue());assertEquals(11,book().current().game().red());assertEquals(1,book().current().gamesWon(1));}
    @Test public void cancellingEverySetEntryStageKeepsScoreOpponentAndSession(){String before=book().encode(),people=names().encode();menu();click("Enter set score");click("Cancel");assertEquals(before,book().encode());click("Enter set score");click("Me won");click("Cancel");assertEquals(before,book().encode());click("Enter set score");click("Me won");click("11–9");click("Review set score");assertTrue(has("replaces the current set"));click("Cancel");assertEquals(before,book().encode());assertEquals(people,names().encode());assertEquals("current",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));}
    @Test public void enteringTheFinalSetSavesTheMatchAndReleasesItsSession(){long started=book().currentStartedAt();menu();currentSet("Me won",7);click("Enter next set score");click("Me won");wheel().setValue(9);click("Review set score");click("Save set score");assertTrue(book().current().complete());assertEquals(1,book().count());MatchResult r=book().result("current");assertEquals(started,r.startedAt);assertEquals(0,r.finishedAt);assertEquals(2,r.gamesWon(0));assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertEquals(0,activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);assertNotNull(button("Undo entered set"));}
    @Test public void undoEnteredSetRequiresConfirmationAndNeverFakesAnIndividualRally(){menu();currentSet("Me won",7);click("Scoreboard");activity.action(TouchTargets.UNDO);assertTrue(has("point order was not recorded"));click("Cancel");assertTrue(book().current().game().entered());activity.action(TouchTargets.UNDO);click("Undo entered set");assertFalse(book().current().hasEnteredSets());assertEquals(0,book().current().game().blue());assertEquals(0,book().current().game().red());}
    @Test public void wholeMatchEntryUsesSavedNameAndDatePickersAndKeepsTheLiveMatch(){String current=book().current().encode();long start=book().currentStartedAt();history();assertNotNull(button("Opponent: No name (optional)"));click("Opponent: No name (optional)");click("Alice");click("Date: "+LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy")));click("Yesterday");draftSet(1,"Me won",7);draftSet(2,"Me won",9);Button save=button("Save match result");assertTrue(save.isEnabled());save.performClick();assertEquals(1,book().count());MatchResult saved=book().newestFirst().get(0);assertEquals(LocalDate.now().minusDays(1).toString(),saved.date);assertEquals("Alice",names().nameFor(saved.id));assertEquals(0,saved.startedAt);assertEquals(0,saved.finishedAt);assertEquals(current,book().current().encode());assertEquals(start,book().currentStartedAt());assertEquals(martin,names().opponentId("current"));assertEquals("current",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));save.performClick();assertEquals(1,book().count());}
    @Test public void wholeBestOfFiveCanBeRecordedWithoutChoosingAName(){history();click("Best of 5");assertFalse(button("Save match result").isEnabled());draftSet(1,"Opponent won",7);draftSet(2,"Opponent won",8);assertFalse(button("Save match result").isEnabled());draftSet(3,"Opponent won",9);click("Save match result");MatchResult r=book().newestFirst().get(0);assertEquals(5,r.bestOf);assertEquals(1,r.winner());assertEquals(3,r.gamesWon(1));assertEquals("",names().opponentId(r.id));assertEquals("Martin",names().nameFor("current"));}
    @Test public void dateWheelsNeedNoKeyboardAndClampALeapDayWhenChangingYear(){history();click("Date: "+LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy")));click("Year: "+LocalDate.now().getYear());noKeyboard();wheel().setValue(2024);click("Use year");click("Month: "+LocalDate.now().getMonth().getDisplayName(java.time.format.TextStyle.SHORT,java.util.Locale.getDefault()));noKeyboard();wheel().setValue(2);click("Use month");click("Day: "+LocalDate.now().getDayOfMonth());noKeyboard();wheel().setValue(29);click("Use day");click("Year: 2024");wheel().setValue(2025);click("Use year");click("Use date");assertNotNull(button("Date: 28.02.2025"));assertEquals(0,book().count());}
    @Test public void cancellingADateSelectionKeepsTheDraftDate(){history();String today="Date: "+LocalDate.now().format(java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy"));click(today);click("Year: "+LocalDate.now().getYear());wheel().setValue(2024);click("Use year");click("Cancel");assertNotNull(button(today));}
    @Test public void b3MigrationKeepsAllRecoveryBackupsAndTheRetiredOutcome()throws Exception{close();String old=new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v3-retired.txt")),StandardCharsets.UTF_8).trim();preferences.edit().clear().putString("match_book",old).putString("match_book_v1_backup","keep-v1").putString("match_book_v2_backup","keep-v2").commit();launch();assertEquals(old,preferences.getString("match_book_v3_backup",""));assertEquals("keep-v1",preferences.getString("match_book_v1_backup",""));assertEquals("keep-v2",preferences.getString("match_book_v2_backup",""));assertTrue(preferences.getString("match_book","").startsWith("B4:"));assertTrue(book().current().retired());assertTrue(book().result("v3-past-retired").retired());close();launch();assertEquals(old,preferences.getString("match_book_v3_backup",""));}
    @Test public void cancellingWholeMatchEntryKeepsTheScoreAndAllAssignments(){String before=book().encode(),people=names().encode();history();click("Opponent: No name (optional)");click("Alice");draftSet(1,"Me won",7);click("Cancel");assertEquals(before,book().encode());assertEquals(people,names().encode());assertEquals("current",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));}
    @Test public void continueAfterAnEnteredSetStartsPlayAndKeepsItsRecordedStart(){close();preferences.edit().clear().putString("match_book",new MatchBook(new MatchState("fresh",3)).encode()).putBoolean("asked_match_notification",true).commit();launch();menu();long before=System.currentTimeMillis();currentSet("Me won",7);long started=book().currentStartedAt();assertTrue(started>=before&&started<=System.currentTimeMillis());assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));click("Score next set live");assertEquals(2,book().current().gameCount());assertEquals("fresh",preferences.getString(MatchDisplayPolicy.ACTIVE_MATCH,""));activity.action(TouchTargets.BLUE);assertEquals(1,book().current().game().blue());assertEquals(started,book().currentStartedAt());}
    @Test public void anUnsetStartIsRecordedOnlyOnSaveAndSurvivesReopening(){close();preferences.edit().clear().putString("match_book",new MatchBook(new MatchState("fresh",3)).encode()).putBoolean("asked_match_notification",true).commit();launch();menu();click("Enter set score");click("Me won");click("Review set score");assertTrue(has("current date and time as the match start"));assertEquals(0,book().currentStartedAt());click("Cancel");assertEquals(0,book().currentStartedAt());click("Enter set score");click("Me won");click("Review set score");long before=System.currentTimeMillis();click("Save set score");long started=book().currentStartedAt();assertTrue(started>=before&&started<=System.currentTimeMillis());assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));close();launch();assertEquals(started,book().currentStartedAt());assertTrue(book().current().game().entered());assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));}
    @Test public void aPreviouslyUntimedManualMatchUsesSaveTimeForItsMissingStart()throws Exception{close();String old=new String(Files.readAllBytes(Paths.get("android/test-fixtures/book-v4-manual-untimed.txt")),StandardCharsets.UTF_8).trim();preferences.edit().clear().putString("match_book",old).putBoolean("asked_match_notification",true).commit();launch();assertEquals(0,book().currentStartedAt());menu();click("Enter set score");click("Opponent won");click("Review set score");assertTrue(has("current date and time as the match start"));long before=System.currentTimeMillis();click("Save set score");long started=book().currentStartedAt();assertTrue(started>=before&&started<=System.currentTimeMillis());assertEquals(11,book().current().game(0).blue());assertEquals(1,book().current().gamesWon(1));assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));click("Enter next set score");click("Me won");click("Review set score");assertFalse(has("current date and time as the match start"));click("Save set score");assertEquals(started,book().currentStartedAt());}
    @Test public void enteringHistoricalResultsDoesNotActivateAnIdleWatch(){close();preferences.edit().clear().putString("match_book",new MatchBook(new MatchState("idle",3)).encode()).putBoolean("asked_match_notification",true).commit();launch();shadowOf(RuntimeEnvironment.getApplication()).clearStartedServices();history();draftSet(1,"Me won",7);draftSet(2,"Me won",8);click("Save match result");assertEquals(1,book().count());assertFalse(preferences.contains(MatchDisplayPolicy.ACTIVE_MATCH));assertEquals("idle",book().current().id());assertNull(shadowOf(RuntimeEnvironment.getApplication()).getNextStartedService());assertEquals(0,activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
}
